 90	function reasoningLevelsForModel(model: Record<string, unknown>): ReasoningLevel[] {
 91	  if (model.reasoning !== true) return [];
 92	  const options = Array.isArray(model.reasoning_options) ? model.reasoning_options : [];
 93	  const effort = options.find((option) => isRecord(option) && option.type === "effort");
 94	  const advertised = isRecord(effort) && Array.isArray(effort.values)
 95	    ? effort.values.map(normalizeReasoningLevel).filter((level): level is ReasoningLevel => level !== null)
 96	    : [];
 97	  const levels = new Set<ReasoningLevel>(["off", ...advertised]);
 98	
 99	  // Budget-only models expose a numeric floor instead of named effort tiers.
100	  // Mobile maps the shared ladder to provider-specific token budgets, so all
101	  // named controls are usable for that shape.
102	  if (advertised.length === 0 && options.some((option) => isRecord(option) && option.type === "budget_tokens")) {
103	    REASONING_ORDER.forEach((level) => levels.add(level));
104	  }
105	  // Older cached/public records may only carry `reasoning: true`. Retain the
106	  // safe shared ladder rather than hiding a capability the provider supports.
107	  if (levels.size === 1) REASONING_ORDER.forEach((level) => levels.add(level));
108	  return REASONING_ORDER.filter((level) => levels.has(level));
109	}
