111	export function isCatalogModel(value: unknown): value is CatalogModel {
112	  if (!isRecord(value) || !PROVIDER_IDS.has(value.provider as ProviderId)) return false;
113	  const provider = value.provider as ProviderId;
114	  return typeof value.id === "string"
115	    && value.id.length > 0
116	    && value.key === catalogKey(provider, value.id)
117	    && typeof value.providerLabel === "string"
118	    && typeof value.name === "string"
119	    && typeof value.description === "string"
120	    && typeof value.reasoning === "boolean"
121	    && Array.isArray(value.reasoningLevels)
122	    && value.reasoningLevels.every((level) => REASONING_LEVELS.has(level as ReasoningLevel))
123	    && typeof value.temperature === "boolean"
124	    && typeof value.vision === "boolean"
125	    && typeof value.contextWindow === "number"
126	    && Number.isFinite(value.contextWindow)
127	    && value.contextWindow >= 0
128	    && typeof value.maxOutputTokens === "number"
129	    && Number.isFinite(value.maxOutputTokens)
130	    && value.maxOutputTokens >= 0
131	    && value.transport === NATIVE_PROVIDER_TRANSPORT[provider]
132	    && MODEL_SOURCES.has(value.source as CatalogModel["source"]);
133	}
