139	/**
140	 * Validate and normalize the public models.dev provider catalog. Only models
141	 * that the native chat transports can actually call are exposed.
142	 */
143	export function parseModelsDevCatalog(payload: unknown): CatalogModel[] {
144	  if (!isRecord(payload)) throw new Error("models.dev returned an invalid catalog.");
145	  const models: CatalogModel[] = [];
146	
147	  for (const [providerKey, providerValue] of Object.entries(payload)) {
148	    if (!MODELS_DEV_PROVIDERS.has(providerKey as ModelsDevProviderId) || !isRecord(providerValue)) continue;
149	    const provider = providerKey as ModelsDevProviderId;
150	    const providerLabel = typeof providerValue.name === "string"
151	      ? providerValue.name
152	      : providerDefinition(provider).label;
153	    if (!isRecord(providerValue.models)) continue;
154	
155	    for (const [recordKey, modelValue] of Object.entries(providerValue.models)) {
156	      if (!isRecord(modelValue)) continue;
157	      const id = typeof modelValue.id === "string" && modelValue.id.trim() ? modelValue.id.trim() : recordKey.trim();
158	      if (!id) continue;
159	      const modalities = isRecord(modelValue.modalities) ? modelValue.modalities : {};
160	      const inputs = stringArray(modalities.input);
161	      const outputs = stringArray(modalities.output);
162	      const limits = isRecord(modelValue.limit) ? modelValue.limit : {};
163	      const contextWindow = finiteNonNegative(limits.context);
164	
165	      // Image, speech, embedding, and other non-chat entries share the public
166	      // catalog. The mobile Tutor can only use models that produce text.
167	      if (!outputs.includes("text") || contextWindow <= 0 || !isNativeTransportCompatible(provider, id)) continue;
168	
169	      models.push({
170	        key: catalogKey(provider, id),
171	        provider,
172	        providerLabel,
173	        id,
174	        name: typeof modelValue.name === "string" && modelValue.name.trim() ? modelValue.name.trim() : id,
175	        description: typeof modelValue.description === "string" ? modelValue.description.trim() : "",
176	        reasoning: modelValue.reasoning === true,
177	        reasoningLevels: reasoningLevelsForModel(modelValue),
178	        temperature: modelValue.temperature === true,
179	        vision: inputs.includes("image"),
180	        contextWindow,
181	        maxOutputTokens: finiteNonNegative(limits.output),
182	        transport: NATIVE_PROVIDER_TRANSPORT[provider],
183	        source: "models.dev",
184	      });
185	    }
186	  }
187	
188	  if (models.length === 0) throw new Error("models.dev returned no compatible chat models.");
189	  return dedupeModels(models).sort(compareModels);
190	}
